"""Builds departure boards from a timetable feed. See /app/docs."""
import csv
import json
import sys
from datetime import date, datetime, timedelta, timezone
from pathlib import Path
from zoneinfo import ZoneInfo


def read_csv(d, name):
    p = Path(d) / name
    if not p.exists():
        return []
    with open(p, encoding="utf-8-sig", newline="") as f:
        reader = csv.reader(f)
        header = None
        rows = []
        for r in reader:
            if not any(c.strip() for c in r):
                continue
            if header is None:
                header = [c.strip() for c in r]
                continue
            row = {}
            for i, h in enumerate(header):
                v = r[i].strip() if i < len(r) else ""
                if h not in row:
                    row[h] = v
            rows.append(row)
        return rows


def parse_time(s):
    h, m, sec = s.split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def parse_date(s):
    return date(int(s[0:4]), int(s[4:6]), int(s[6:8]))


_tzc = {}


def tz(name):
    if name not in _tzc:
        _tzc[name] = ZoneInfo(name)
    return _tzc[name]


def origin(d, tzname):
    noon = datetime(d.year, d.month, d.day, 12, 0, 0, tzinfo=tz(tzname))
    return noon.astimezone(timezone.utc) - timedelta(hours=12)


def fmt(instant, tzname):
    dt = instant.astimezone(tz(tzname))
    off = dt.utcoffset()
    secs = int(off.total_seconds())
    sign = "+" if secs >= 0 else "-"
    secs = abs(secs)
    return dt.strftime("%Y-%m-%dT%H:%M:%S") + "%s%02d:%02d" % (sign, secs // 3600, secs % 3600 // 60)


def main(inp, outp):
    request = json.loads(Path(inp, "request.json").read_text(encoding="utf-8-sig"))
    dates = sorted(set(request["service_dates"]))

    agencies = read_csv(inp, "agency.txt")
    agency_tz = {a["agency_id"]: a["agency_timezone"] for a in agencies}
    default_agency = agencies[0]["agency_id"]
    default_tz = agencies[0]["agency_timezone"]

    stops = {s["stop_id"]: s for s in read_csv(inp, "stops.txt")}
    routes = {r["route_id"]: r for r in read_csv(inp, "routes.txt")}
    trips = {t["trip_id"]: t for t in read_csv(inp, "trips.txt")}

    cal = {c["service_id"]: c for c in read_csv(inp, "calendar.txt")}
    cdates = {}
    for r in read_csv(inp, "calendar_dates.txt"):
        cdates[(r["service_id"], r["date"])] = r["exception_type"]
    freqs = {}
    for r in read_csv(inp, "frequencies.txt"):
        freqs.setdefault(r["trip_id"], []).append(r)

    st_by_trip = {}
    for r in read_csv(inp, "stop_times.txt"):
        st_by_trip.setdefault(r["trip_id"], []).append(r)

    def is_board_stop(s):
        lt = s.get("location_type", "")
        if lt == "1":
            return True
        if lt in ("", "0") and not s.get("parent_station", ""):
            return True
        return False

    def board_of(stop_id):
        s = stops[stop_id]
        p = s.get("parent_station", "")
        if p and s.get("location_type", "") in ("", "0"):
            return p
        return stop_id

    def board_tz(sid):
        return stops[sid].get("stop_timezone", "") or default_tz

    def runs(service_id, d):
        ex = cdates.get((service_id, d.strftime("%Y%m%d")))
        if ex == "1":
            return True
        if ex == "2":
            return False
        c = cal.get(service_id)
        if not c:
            return False
        if not (parse_date(c["start_date"]) <= d <= parse_date(c["end_date"])):
            return False
        day = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"][d.weekday()]
        return c.get(day, "") == "1"

    # Precompute per trip: ordered stops with times, departures, headsigns.
    trip_info = {}
    for tid, rows in st_by_trip.items():
        if tid not in trips:
            continue
        rows = sorted(rows, key=lambda r: int(r["stop_sequence"]))
        n = len(rows)
        times = []
        for r in rows:
            t = r.get("departure_time", "") or r.get("arrival_time", "")
            times.append(parse_time(t) if t else None)
        known = [i for i, t in enumerate(times) if t is not None]
        for a, b in zip(known, known[1:]):
            steps = b - a
            for i in range(a + 1, b):
                times[i] = times[a] + (times[b] - times[a]) * (i - a) // steps
        last = stops[rows[-1]["stop_id"]]
        last_board = stops[board_of(rows[-1]["stop_id"])]
        trip = trips[tid]
        deps = []
        for i, r in enumerate(rows):
            if i == n - 1 or r.get("pickup_type", "") == "1":
                continue
            hs = r.get("stop_headsign", "") or trip.get("trip_headsign", "") or last_board["stop_name"]
            deps.append((times[i], r["stop_id"], hs))
        trip_info[tid] = (times[0], deps)

    boards = {}
    for sid, s in stops.items():
        if is_board_stop(s):
            for ds in dates:
                boards[(sid, ds)] = []

    for ds in dates:
        d = date.fromisoformat(ds)
        for tid, (first, deps) in trip_info.items():
            trip = trips[tid]
            if not runs(trip["service_id"], d):
                continue
            route = routes[trip["route_id"]]
            agency = route.get("agency_id", "") or default_agency
            label = route.get("route_short_name", "") or route.get("route_long_name", "")
            org = origin(d, agency_tz[agency])
            entries = []  # (secs, until_secs, headway, stop_id, headsign)
            if tid in freqs:
                for w in freqs[tid]:
                    start = parse_time(w["start_time"])
                    end = parse_time(w["end_time"])
                    hw = int(w["headway_secs"])
                    starts = list(range(start, end, hw)) if start < end else []
                    if not starts:
                        continue
                    exact = w.get("exact_times", "") == "1"
                    for t, stop_id, hs in deps:
                        off = t - first
                        if exact:
                            for s0 in starts:
                                entries.append((s0 + off, None, None, stop_id, hs))
                        else:
                            entries.append((starts[0] + off, starts[-1] + off, hw, stop_id, hs))
            else:
                for t, stop_id, hs in deps:
                    entries.append((t, None, None, stop_id, hs))
            for secs, until, hw, stop_id, hs in entries:
                bid = board_of(stop_id)
                btz = board_tz(bid)
                inst = org + timedelta(seconds=secs)
                dep = {
                    "kind": "scheduled" if hw is None else "interval",
                    "time": fmt(inst, btz),
                    "until": None if until is None else fmt(org + timedelta(seconds=until), btz),
                    "headway_secs": hw,
                    "route": label,
                    "headsign": hs,
                    "trip": tid,
                    "platform": stops[stop_id].get("platform_code", "") or None,
                    "agency": agency,
                }
                key = (inst, label, hs, tid, dep["platform"] is not None, dep["platform"] or "")
                boards[(bid, ds)].append((key, dep))

    out_boards = []
    for (sid, ds) in sorted(boards, key=lambda k: (k[0], k[1])):
        items = sorted(boards[(sid, ds)], key=lambda x: x[0])
        out_boards.append({
            "stop_id": sid,
            "name": stops[sid]["stop_name"],
            "timezone": board_tz(sid),
            "service_date": ds,
            "departures": [x[1] for x in items],
        })
    result = {"service_dates": dates, "boards": out_boards}
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
